# Differential motif enrichment among accessible peaks.
# Requires PeakMatrix and motif annotation generated by addMotifAnnotations().
source("R/common.R")
suppressPackageStartupMessages({library(ArchR);library(ComplexHeatmap)})
stopifnot(inherits(proj1,"ArchRProject"))
stopifnot("PeakMatrix" %in% getAvailableMatrices(proj1))
stopifnot(!is.null(getPositions(proj1,name="Motif")))
meta <- as.data.frame(getCellColData(proj1))
proj1$plot_group <- as.character(standard_group(meta$group))
dir <- output_dir("snATAC_Motif")
marker_peaks <- getMarkerFeatures(ArchRProj=proj1,useMatrix="PeakMatrix",groupBy="plot_group",
                                  bias=c("TSSEnrichment","log10(nFrags)"),testMethod="wilcoxon")
motif_enrichment <- peakAnnoEnrichment(seMarker=marker_peaks,ArchRProj=proj1,
                                       peakAnnotation="Motif",
                                       cutOff="FDR <= 0.1 & Log2FC >= 0.5")
heat <- plotEnrichHeatmap(seEnrich=motif_enrichment,n=40,transpose=TRUE)
pdf(file.path(dir,"Differential_Motif_Enrichment.pdf"),width=10,height=9)
ComplexHeatmap::draw(heat);dev.off()
png(file.path(dir,"Differential_Motif_Enrichment.png"),width=10,height=9,units="in",res=600)
ComplexHeatmap::draw(heat);dev.off()
message("Motif enrichment complete. No CSV generated.")
